CREATE OR REPLACE FUNCTION public.validate_task_dependencies() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NEW.parent_id=NEW.id THEN RAISE EXCEPTION 'A task cannot be its own parent'; END IF; IF NEW.id=ANY(NEW.predecessor_ids) THEN RAISE EXCEPTION 'A task cannot depend on itself'; END IF; IF EXISTS(SELECT 1 FROM unnest(NEW.predecessor_ids) x(id) WHERE NOT EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=x.id AND t.project_id=NEW.project_id)) THEN RAISE EXCEPTION 'Every predecessor must be an accessible task in the same project'; END IF; IF EXISTS(WITH RECURSIVE chain AS (SELECT t.id,t.predecessor_ids,ARRAY[t.id] path FROM public.tasks t WHERE t.id=ANY(NEW.predecessor_ids) UNION ALL SELECT t.id,t.predecessor_ids,c.path || t.id FROM chain c JOIN public.tasks t ON t.id=ANY(c.predecessor_ids) WHERE NOT t.id=ANY(c.path)) SELECT 1 FROM chain WHERE NEW.id=ANY(predecessor_ids)) THEN RAISE EXCEPTION 'Task dependencies cannot contain a cycle'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.validate_task_dependencies() FROM PUBLIC, anon;
CREATE TRIGGER validate_task_dependencies BEFORE INSERT OR UPDATE OF predecessor_ids,parent_id,project_id ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.validate_task_dependencies();